def f(x):
    return np.array([x[1], -np.sin(x[0]) - x[1]])

def g(x):
    return np.array([0.0, 1.0])

def h(x):
    return x[0]

def num_dir_deriv(func, x, v, eps=1e-6):
    """向量场 v 方向上 func 的方向导数（中心差分）"""
    return (func(x + eps*v) - func(x - eps*v)) / (2*eps)

def num_jac_vec(func, x, v, eps=1e-6):
    """数值 Jacobian 作用在向量 v 上，即 (d func/d x) v"""
    n = len(x)
    J = np.zeros((n, n))
    for i in range(n):
        e = np.zeros(n); e[i] = eps
        J[:, i] = (func(x + e) - func(x - e)) / (2*eps)
    return J @ v

x0 = np.array([0.7, -0.4])
print("状态点 x0 =", x0)
print()
print("L_g h 数值 =", num_dir_deriv(h, x0, g(x0)), " 手算 = 0")
print("L_f h 数值 =", num_dir_deriv(h, x0, f(x0)), " 手算 =", x0[1])
Lf_h = lambda x: num_dir_deriv(h, x, f(x))
print("L_g L_f h 数值 =", num_dir_deriv(Lf_h, x0, g(x0)), " 手算 = 1")
print("L_f^2 h 数值 =", num_dir_deriv(Lf_h, x0, f(x0)),
      " 手算 =", -np.sin(x0[0]) - x0[1])
print()
# Lie 括号 ad_f g = (dg/dx) f - (df/dx) g；本例 g 为常向量场，故 ad_f g = -(df/dx) g
ad_num = num_jac_vec(g, x0, f(x0)) - num_jac_vec(f, x0, g(x0))
print("ad_f g 数值 =", np.round(ad_num, 6), " 手算 = [-1, 1]")

